#!/usr/bin/env python3
"""Compile Ashfen Coast pack.json from authored data plus the salvage catalog."""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "content" / "ashfen" / "pack.json"

ADJS = [
    "bent",
    "rusted",
    "salt",
    "tarred",
    "cracked",
    "braided",
    "pitted",
    "pale",
    "hooked",
    "knotted",
]
NOUNS = [
    "hook",
    "spike",
    "buckle",
    "shackle",
    "needle",
    "clasp",
    "ring",
    "wedge",
    "plate",
    "peg",
]


def salvage_catalog() -> tuple[dict[str, dict], list[str]]:
    items: dict[str, dict] = {}
    order: list[str] = []
    n = 0
    for adj in ADJS:
        for noun in NOUNS:
            item_id = f"salvage_{n:03d}"
            items[item_id] = {"name": f"{adj} {noun}", "kind": "salvage"}
            order.append(item_id)
            n += 1
    return items, order


def action(
    aid: str,
    label: str,
    group: str,
    when: dict,
    text: str,
    effects: list | None = None,
) -> dict:
    spec = {
        "id": aid,
        "label": label,
        "group": group,
        "when": when,
        "text": text,
        "effects": effects or [],
    }
    return spec


